def choose_move(observation):
    def p(v, d=(0, 0)):
        try:
            if isinstance(v, (list, tuple)) and len(v) >= 2:
                return int(v[0]), int(v[1])
        except:
            pass
        return d

    def sgn(x):
        return -1 if x < 0 else (1 if x > 0 else 0)

    def man(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step(a, b):
        return [sgn(b[0] - a[0]), sgn(b[1] - a[1])]

    def add_pos(container, v):
        try:
            if isinstance(v, dict):
                if "position" in v:
                    add_pos(container, v.get("position"))
                elif "pos" in v:
                    add_pos(container, v.get("pos"))
                elif "x" in v and "y" in v:
                    container.add((int(v.get("x")), int(v.get("y"))))
            elif isinstance(v, (list, tuple)):
                if len(v) >= 2 and not isinstance(v[0], (list, tuple, dict)):
                    container.add(p(v))
                else:
                    for q in v:
                        add_pos(container, q)
        except:
            pass

    me = p(observation.get("self_position"))
    opp = p(observation.get("opponent_position"), me)

    obstacles = set()
    for q in observation.get("obstacles") or []:
        add_pos(obstacles, q)

    resources = []
    for q in observation.get("resources") or []:
        if isinstance(q, dict):
            q = q.get("position", q.get("pos", q))
        resources.append(p(q))

    targets = []
    for k in ("targets", "target_positions", "goals", "goal_positions", "objectives", "objective_positions",
              "frontier", "frontiers", "neutral_positions", "unclaimed", "unclaimed_positions",
              "territory", "territory_positions", "capture_points", "capture_positions"):
        v = observation.get(k)
        if v is not None:
            tmp = set()
            add_pos(tmp, v)
            for t in tmp:
                if t not in targets:
                    targets.append(t)

    if resources:
        tgt = min(resources, key=lambda r: (man(me, r), man(opp, r), r[0], r[1]))
    elif targets:
        tgt = min(targets, key=lambda r: (man(me, r), man(opp, r), r[0], r[1]))
    else:
        tgt = opp

    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1), (0, 0)]
    best = [0, 0]
    best_score = None

    for d in dirs:
        nx, ny = me[0] + d[0], me[1] + d[1]
        if (nx, ny) in obstacles:
            continue
        dist_t = man((nx, ny), tgt)
        dist_o = man((nx, ny), opp)
        if tgt == opp:
            score = (dist_t, -dist_o, abs(d[0]) + abs(d[1]), d[0], d[1])
        else:
            score = (dist_t, dist_o, abs(d[0]) + abs(d[1]), d[0], d[1])
        if best_score is None or score < best_score:
            best_score = score
            best = [d[0], d[1]]

    if best_score is not None:
        return best

    return [0, 0]

